uint64_t Hash(std::string_view s){uint64_t h=14695981039346656037ULL;for(uint8_t c:s)h=(h^c)*1099511628211ULL;return h;}
std::string OriginalAux(const char* name){const auto s=Read(sourceRoot+"/rts/Rendering/Map/InfoTexture/Modern/"+name+".cpp");const auto begin=s.find("const std::string fragmentCode = R\"(")+strlen("const std::string fragmentCode = R\"(");const auto end=s.find(")\";",begin);Check(begin<s.size()&&end!=s.npos,"Original auxiliary shader extraction");return s.substr(begin,end-begin);}
