	std::vector<std::vector<uint32_t>> Render(const NativeMetalInfoFrame& f){CGLSetCurrentContext(context);glBindVertexArray(vao);glDisable(GL_DEPTH_TEST);glDisable(GL_STENCIL_TEST);glDisable(GL_SCISSOR_TEST);glDisable(GL_CULL_FACE);glDisable(GL_DITHER);glColorMask(true,true,true,true);if(map!=f.mapIdentity||generation!=f.modeGeneration){Check(!f.updates.empty()&&f.updates[0].clear,"Original new mode has black clear");glDeleteTextures(1,&info);glGenTextures(1,&info);glBindTexture(GL_TEXTURE_2D,info);glTexImage2D(GL_TEXTURE_2D,0,GL_RGB10_A2,f.paddedSquaresX,f.paddedSquaresZ,0,GL_RGBA,GL_UNSIGNED_INT_2_10_10_10_REV,nullptr);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);map=f.mapIdentity;generation=f.modeGeneration;serial=0;}
