std::vector<std::vector<uint32_t>> Native(MetalInfoGPU&gpu,std::shared_ptr<const NativeMetalInfoFrame> f){RuntimeLease lease;const auto start=Clock::now();double ms=0;auto prepared=gpu.Prepare(lease,f,true,ms);auto image=prepared->Info();Check(image!=nil,"Actual native metal info image");std::vector<id<MTLBuffer>> buffers;for(NSUInteger level=0;level<image.mipmapLevelCount;++level){auto bytes=[lease.Device()newBufferWithLength:256*std::max(NSUInteger(1),image.height>>level) options:MTLResourceStorageModeShared];Check(bytes!=nil,"Native metal mip readback buffer");lease.AddAllocation(bytes);buffers.push_back(bytes);}lease.CommitResources();auto cmd=lease.Begin("Original metal info / LOS / temporal RGBA10 oracle");prepared->EncodeDependencies(cmd);auto e=[cmd computeCommandEncoder];Check(e!=nil,"Native metal mip copy encoder");[e barrierAfterQueueStages:MTLStageFragment|MTLStageBlit beforeStages:MTLStageBlit visibilityOptions:MTL4VisibilityOptionDevice];for(NSUInteger level=0;level<buffers.size();++level)[e copyFromTexture:image sourceSlice:0 sourceLevel:level sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(std::max(NSUInteger(1),image.width>>level),std::max(NSUInteger(1),image.height>>level),1) toBuffer:buffers[level] destinationOffset:0 destinationBytesPerRow:256 destinationBytesPerImage:0];[e endEncoding];lease.SubmitAndWait(start,renders++);prepared->DidComplete();std::vector<std::vector<uint32_t>> out;for(NSUInteger level=0;level<buffers.size();++level){unsigned x=std::max(NSUInteger(1),image.width>>level),z=std::max(NSUInteger(1),image.height>>level);out.emplace_back(x*z);for(unsigned row=0;row<z;++row)memcpy(out.back().data()+row*x,static_cast<const uint8_t*>(buffers[level].contents)+256*row,x*4);}return out;}
std::shared_ptr<const NativeMetalDensity> Density(unsigned shift=0){auto d=std::make_shared<NativeMetalDensity>();d->width=12;d->height=6;for(unsigned z=0;z<6;++z)for(unsigned x=0;x<12;++x)d->values.push_back((x*23+z*31+shift)%256);return d;}
std::shared_ptr<const NativeMetalExtraction> Extraction(bool global=false,unsigned scale=1){auto e=std::make_shared<NativeMetalExtraction>();e->width=12;e->height=6;e->losWidth=3*scale;e->losHeight=2*scale;e->globalLos=global;for(unsigned z=0;z<6;++z)for(unsigned x=0;x<12;++x)e->depth.push_back((int((x+z*2)%7)-1)*.0004f);for(unsigned z=0;z<e->losHeight;++z)for(unsigned x=0;x<e->losWidth;++x)e->los.push_back(x<e->losWidth/2?0:7);return e;}
