		auto actual=Native(gpu,actualFrame);Check(actual.size()==expected.size(),"Original complete metal mip count");unsigned local=0,difference=0,painted=0;for(size_t level=0;level<actual.size();++level){Check(actual[level].size()==expected[level].size(),"Original mip dimensions");for(size_t n=0;n<actual[level].size();++n){for(unsigned channel=0;channel<4;++channel){unsigned mask=channel==3?3:1023,shift=channel*10;const auto a=(actual[level][n]>>shift)&mask,b=(expected[level][n]>>shift)&mask;const unsigned error=std::abs(int(a)-int(b));local=std::max(local,error);difference+=error!=0;++checks;if(channel==3)Check(a==3&&b==3,"Original RGB-only blend preserves alpha1");else painted+=b!=0;}}}maxError=std::max(maxError,local);changed+=difference;if(caseCount++)cases<<',';cases<<"{\"label\":\""<<label<<"\",\"maxRGB10Error\":"<<local<<",\"differentChannels\":"<<difference<<",\"paintedChannels\":"<<painted<<'}';std::cerr<<label<<" max10 "<<local<<" differences "<<difference<<'\n';Check(local<=1,"Original GLSL/Metal RGB10 metal info mismatch");};
	recorder.SetMode(true,1,24,12,32,16);compare(recorder.Capture(),"original-black-clear");recorder.Retire(recorder.Capture()->serial);auto d=Density();auto e=Extraction();recorder.Update(d,e);compare(recorder.Capture(),"first-original-LOS-extraction");recorder.Retire(recorder.Capture()->serial);for(unsigned n=0;n<4;++n)recorder.Update(d,recorder.NeedsExtractionUpdate()?e:nullptr);compare(recorder.Capture(),"four-quantized-temporal-blends");recorder.Retire(recorder.Capture()->serial);compare(recorder.Capture(),"consumer-replay-does-not-step-history");
