	std::ofstream out(argv[3]);out<<"{\"status\":\"PASS\",\"checks\":"<<checks<<",\"renders\":"<<renders<<",\"maxRGB10Error\":"<<maxError<<",\"differentChannels\":"<<changed<<",\"cases\":["<<cases.str()<<"]}\n";std::cout<<"PASS "<<renders<<" original metal GLSL/Metal submissions / "<<checks<<" checks / maxRGB10 "<<maxError<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}}
